{"command":"python3 - <<'EOF'
import struct, zlib
data = open('/app/service_binary','rb').read()
def u32(off): return struct.unpack_from('<I', data, off)[0]
acc = 0x39223ca7
manifs = [('manifest',0x3140),('fake3',0x3180),('fake2',0x31c0),('fake1',0x3200)]
# Permute: which field is CRC (4-byte LE at 8/12/16/20), which region is enc bitmap
hits=[]
for name, off in manifs:
    fields = {8:u32(off+8),12:u32(off+12),16:u32(off+16),20:u32(off+20)}
    for crc_off, stored in fields.items():
        for enc_off in [8,12,16,20]:
            if enc_off==crc_off: continue
            enc = data[off+enc_off:off+enc_off+4]
            # keys
            for kname,kval in [('acc',acc),('~acc',acc^0xFFFFFFFF),
                               ('bswap',struct.unpack('<I',struct.pack('>I',acc))[0])]:
                dec = bytes(b ^ struct.pack('<I',kval)[i%4] for i,b in enumerate(enc))
                if (zlib.crc32(dec)&0xffffffff)==stored:
                    hits.append((name,f"crc@{crc_off}",f"enc@{enc_off}",kname,dec.hex()))
print("perm hits:", hits if hits else "NONE")
# whole-struct variant: decrypt off20 with acc, zero candidate crc field, crc32(36 bytes)
for name, off in manifs:
    m = bytearray(data[off:off+36])
    dec = bytes(b ^ struct.pack('<I',acc)[i%4] for i,b in enumerate(m[20:24]))
    for crc_off in [8,12,16,20]:
        stored = struct.unpack_from('<I', m, crc_off)[0]
        m2 = bytearray(m); m2[20:24]=dec; m2[crc_off:crc_off+4]=b'\0\0\0\0'
        if (zlib.crc32(bytes(m2))&0xffffffff)==stored:
            hits.append((name,'whole',f"crc@{crc_off}",'acc',''))
print("whole hits:", hits if hits else "NONE")
EOF","description":"Permute CRC and bitmap field positions"}

