import struct, zlib, itertools
def crc(b: bytes) -> int: return zlib.crc32(b) & 0xFFFFFFFF
C = crc(b'\x00\x00\x00\x00')
cols = [crc(struct.pack('<I', 1 << j)) ^ C for j in range(32)]
def invert(target: int) -> int:
    rows = []
    for i in range(32):
        mask = 0
        for j in range(32):
            if (cols[j] >> i) & 1: mask |= (1 << j)
        rows.append([mask, ((target >> i) & 1) ^ ((C >> i) & 1)])
    piv, where = 0, [-1]*32
    for col in range(32):
        sel = next((r for r in range(piv,32) if (rows[r][0]>>col)&1), -1)
        if sel == -1: continue
        rows[piv], rows[sel] = rows[sel], rows[piv]
        where[col] = piv
        for r in range(32):
            if r!=piv and ((rows[r][0]>>col)&1):
                rows[r][0]^=rows[piv][0]; rows[r][1]^=rows[piv][1]
        piv += 1
    x=0
    for j in range(32):
        if where[j]!=-1 and rows[where[j]][1]: x|=(1<<j)
    return x
data = open('/app/service_binary','rb').read()
acc = 0x39223ca7
manifs = [('manifest',0x3140),('fake3',0x3180),('fake2',0x31c0),('fake1',0x3200)]
print("=== exact acc matches across field assignments ===")
for name, off in manifs:
    blob = data[off:off+36]
    for crc_off in [8,12,16,20,24]:
        Sb = blob[crc_off:crc_off+4]
        for enc_off in [8,12,16,20]:
            if enc_off == crc_off: continue
            Eb = blob[enc_off:enc_off+4]
            for send in ['le','be']:
                S = int.from_bytes(Sb, send)
                Pb = invert(S).to_bytes(4,'little')  # P bytes s.t. crc32(Pb)==S
                for kend in ['le','be']:
                    Kb = bytes(e^p for e,p in zip(Eb,Pb))
                    K = int.from_bytes(Kb, kend)
                    if K == acc:
                        print(f"HIT {name}: crc@{crc_off}({send}) enc@{enc_off} key-{kend} P={Pb.hex()}")
print("=== done exact; now near: K^acc with low popcount ===")
for name, off in manifs:
    blob = data[off:off+36]
    for crc_off in [8,12,16,20]:
        Sb = blob[crc_off:crc_off+4]
        for enc_off in [8,12,16,20]:
            if enc_off == crc_off: continue
            Eb = blob[enc_off:enc_off+4]
            for send in ['le','be']:
                S = int.from_bytes(Sb, send)
                Pb = invert(S).to_bytes(4,'little')
                Kb = bytes(e^p for e,p in zip(Eb,Pb))
                for kend in ['le','be']:
                    K = int.from_bytes(Kb, kend)
                    d = K ^ acc
                    if bin(d).count('1') <= 4:
                        print(f"NEAR {name}: crc@{crc_off}({send}) enc@{enc_off} K-{kend}=0x{K:08x} K^acc=0x{d:08x} P={Pb.hex()}")
print("done")
EOF","description":"Match implied keys against acc everywhere"}

