{"command":"python3 - <<'EOF'
import struct, zlib, itertools
def crc(b): return zlib.crc32(b) & 0xFFFFFFFF
data = open('/app/service_binary','rb').read()
def u32(off): return struct.unpack_from('<I', data, off)[0]
stored = {}
for name, off in [('manifest',0x3140),('fake3',0x3180),('fake2',0x31c0),('fake1',0x3200)]:
    stored[name] = (u32(off+8), struct.unpack_from('>I', data, off+8)[0])
from collections import defaultdict
# all u32 with popcount <= 3
vals = [0]
for i in range(32): vals.append(1<<i)
for a,b in itertools.combinations(range(32),2): vals.append((1<<a)|(1<<b))
for a,b,c in itertools.combinations(range(32),3): vals.append((1<<a)|(1<<b)|(1<<c))
print(f"testing {len(vals)} sparse values")
for v in vals:
    for bo in ['little','big']:
        c = crc(v.to_bytes(4,bo))
        for name,(sle,sbe) in stored.items():
            if c==sle: print(f"HIT {name} LE-stored: P=0x{v:08x} (bytes-{bo})")
            if c==sbe: print(f"HIT {name} BE-stored: P=0x{v:08x} (bytes-{bo})")
print("sparse u32 done")
# byte-per-feature: features as bytes 0/1 at 3 of 4 positions
for pos in itertools.permutations(range(4),3):
    for bits in range(8):
        b = bytearray(4)
        for k in range(3):
            b[pos[k]] = (bits>>k)&1
        c = crc(bytes(b))
        for name,(sle,sbe) in stored.items():
            if c==sle or c==sbe: print(f"HIT-BYTE {name}: blob={bytes(b).hex()} pos={pos} bits={bits:03b}")
print("byte-feature done")
EOF","description":"Test sparse bitmaps against stored CRCs","yield_time_ms":180000}

