import struct, zlib
def crc(b): return zlib.crc32(b) & 0xFFFFFFFF
data = open('/app/service_binary','rb').read()
manifs = [('manifest',0x3140),('fake3',0x3180),('fake2',0x31c0),('fake1',0x3200)]
for name, off in manifs:
    blob = bytearray(data[off:off+36])
    S = struct.unpack_from('<I', blob, 8)[0]
    Sbe = struct.unpack_from('>I', blob, 8)[0]
    hits = []
    for a in range(0,36):
        for b in range(a+1,37):
            w = bytes(blob[a:b])
            c = crc(w)
            if c==S: hits.append(f"raw[{a}:{b}]==S_LE")
            if c==Sbe: hits.append(f"raw[{a}:{b}]==S_BE")
            # zero crc field then hash
            z = bytearray(w)
            for i in range(max(a,8), min(b,12)):
                z[i-a]=0
            if bytes(z)!=w:
                c2 = crc(bytes(z))
                if c2==S: hits.append(f"zeroed[{a}:{b}]==S_LE")
                if c2==Sbe: hits.append(f"zeroed[{a}:{b}]==S_BE")
